def transform(grid):
    h,w=len(grid),len(grid[0])
    from collections import Counter
    bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
    fg=next(x for x in Counter(x for row in grid for x in row) if x!=bg)
    out=[row[:] for row in grid]
    # Fill every bounded straight gap in a line of the foreground color.
    for r in range(h):
        cs=[c for c in range(w) if grid[r][c]==fg]
        for a,b in zip(cs,cs[1:]):
            for c in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        rs=[r for r in range(h) if grid[r][c]==fg]
        for a,b in zip(rs,rs[1:]):
            for r in range(a+1,b):
                if grid[r][c]==bg: out[r][c]=2
    return out

